const SUPPORTED_LANGUAGES = ['ru', 'en', 'es', 'fr', 'de', 'it', 'pt', 'tr', 'zh', 'ja', 'ko', 'hi', 'ar'];
SUPPORTED_LANGUAGES.forEach(lang => { i18n[lang] = {}; });

Object.values(I18N_GROUPS).forEach(group => {
    Object.entries(group).forEach(([key, trans]) => {
        SUPPORTED_LANGUAGES.forEach(lang => {
            i18n[lang][key] = trans[lang] || trans.en || trans.ru;
        });
    });
});

